CREATE TABLE public.private_events (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL DEFAULT 'Untitled event', subtitle text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, timezone text NOT NULL DEFAULT 'America/Los_Angeles', location_name text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', contact_email text NOT NULL DEFAULT '', details jsonb NOT NULL DEFAULT '[]', hero jsonb NOT NULL DEFAULT '{}', code_hash text UNIQUE NOT NULL, is_published boolean NOT NULL DEFAULT false, is_locked boolean NOT NULL DEFAULT false, access_version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT event_dates CHECK (ends_at > starts_at)
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.private_events TO authenticated;
GRANT ALL ON public.private_events TO service_role;
ALTER TABLE public.private_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_staff_read ON public.private_events FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY event_edit ON public.private_events FOR ALL TO authenticated USING (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'administrator') OR public.has_role(auth.uid(),'editor') OR public.has_role(auth.uid(),'store_manager')) WITH CHECK (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'administrator') OR public.has_role(auth.uid(),'editor') OR public.has_role(auth.uid(),'store_manager'));
CREATE TABLE public.event_guest_sessions (token_hash text PRIMARY KEY, event_id uuid NOT NULL REFERENCES public.private_events(id) ON DELETE CASCADE, access_version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.event_guest_sessions TO service_role;
ALTER TABLE public.event_guest_sessions ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.event_revoke_access() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF (NEW.is_locked AND NOT OLD.is_locked) OR NEW.code_hash <> OLD.code_hash OR (NOT NEW.is_published AND OLD.is_published) THEN NEW.access_version := OLD.access_version + 1; ELSE NEW.access_version := OLD.access_version; END IF; NEW.updated_at := now(); RETURN NEW; END $$;
CREATE TRIGGER event_revoke BEFORE UPDATE ON public.private_events FOR EACH ROW EXECUTE FUNCTION public.event_revoke_access();
CREATE FUNCTION public.redeem_event_invite(invite_hash text, session_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE ev public.private_events; BEGIN SELECT * INTO ev FROM public.private_events WHERE code_hash = invite_hash FOR UPDATE; IF ev.id IS NULL OR NOT ev.is_published OR ev.is_locked OR ev.ends_at <= now() THEN RETURN NULL; END IF; INSERT INTO public.event_guest_sessions(token_hash,event_id,access_version) VALUES(session_hash,ev.id,ev.access_version); RETURN ev.id; END $$;
REVOKE ALL ON FUNCTION public.redeem_event_invite(text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.redeem_event_invite(text,text) TO service_role;
CREATE FUNCTION public.read_guest_event(session_hash text) RETURNS SETOF public.private_events LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ SELECT e.* FROM public.private_events e JOIN public.event_guest_sessions s ON s.event_id=e.id WHERE s.token_hash=session_hash AND s.access_version=e.access_version AND e.is_published AND NOT e.is_locked AND e.ends_at > now(); $$;
REVOKE ALL ON FUNCTION public.read_guest_event(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.read_guest_event(text) TO service_role;
CREATE POLICY event_media_staff ON storage.objects FOR ALL TO authenticated USING (bucket_id='event-media' AND (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'administrator') OR public.has_role(auth.uid(),'editor') OR public.has_role(auth.uid(),'store_manager'))) WITH CHECK (bucket_id='event-media' AND (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'administrator') OR public.has_role(auth.uid(),'editor') OR public.has_role(auth.uid(),'store_manager')));